lines=open(p, encoding='utf-8', errors='replace').read().splitlines()
# find any tool_result text mentioning these strings anywhere (not only WebSearch)
needles=['NZS 4121','assets.gov.ie','finlex','BraunAbility','Adaptations without delay','edilex','2022']
found={n:[] for n in needles}
for ln,l in enumerate(lines):
    try: d=json.loads(l)
    except Exception: continue
    if d.get('type')!='user': continue
    c=d.get('message',{}).get('content')
    if not isinstance(c,list): continue
    for part in c:
        if isinstance(part,dict) and part.get('type')=='tool_result':
            cc=part.get('content')
            if isinstance(cc,list): cc=' '.join(x.get('text','') for x in cc if isinstance(x,dict))
            cc=str(cc)
            for n in needles:
                if n in cc: found[n].append((ln, d.get('timestamp','')[11:19], cc[:120].replace('\n',' ')))
for n,v in found.items():
    print(f'{n}: {len(v)} tool_results'); 
    for x in v[:4]: print('   ', x)
PY

